function departmentGroup(value){const name=String(value||"").trim();for(const [group,aliases] of Object.entries(departmentAliases)){if(name===group||aliases.includes(name))return group}return name}
function sameDepartment(first,second){return departmentGroup(first)===departmentGroup(second)}
