function getStoredCases(){try{return JSON.parse(localStorage.getItem("bcCases")||"null")}catch{return null}}
function mergeCases(){
  const local=window.localCases||[];
  const company=window.companyCases||[];
  const stored=getStoredCases()||[];
  const localById=new Map(local.map(c=>[c.id,c]));
  const source=[...company.map(c=>localById.has(c.id)?{...c,...localById.get(c.id)}:c),...local.filter(c=>!company.some(x=>x.id===c.id))];
  const sourceIds=new Set(source.map(c=>c.id));
  return [...source,...stored.filter(c=>!sourceIds.has(c.id))];
}
