function pensionNumber(value){return Number(String(value||0).replace(/[^0-9.-]/g,""))||0}
function pensionCalculate(d){const weeks=pensionNumber(d.weeks),ibl=pensionNumber(d.ibl),paid=pensionNumber(d.paid),factors=String(d.factors||"").split(/\n|,/).map(x=>x.trim()).filter(Boolean);let estimated=0,formula="";if(d.regime==="RPM - Colpensiones"){const extra=Math.max(0,weeks-1300);const rate=Math.max(.55,Math.min(.8,.65+.015*Math.floor(extra/50)));estimated=ibl*rate;formula=`IBL $${ibl.toLocaleString("es-CO")} × ${(rate*100).toFixed(2)}% (${weeks.toLocaleString("es-CO")} semanas)`}else{const capital=pensionNumber(d.capital);estimated=capital/180;formula=`Capital $${capital.toLocaleString("es-CO")} ÷ 180 (estimación referencial RAIS)`}if(d.procedure.includes("Indemnización")&&d.regime==="RPM - Colpensiones")estimated=ibl/4.33*weeks*(pensionNumber(d.contributionRate)||.16);const flags=[];if(!d.dob||!d.sex)flags.push("Faltan datos de edad y sexo para verificar requisitos.");if(!weeks)flags.push("No se ingresaron semanas cotizadas.");if(d.regime==="RPM - Colpensiones"&&!ibl)flags.push("Falta el IBL o promedio salarial que soporta la liquidación.");if(!factors.length)flags.push("No se detallaron factores salariales; revisar salario, primas, horas extra, bonificaciones y demás conceptos según el caso.");if(paid&&Math.abs(estimated-paid)>1)flags.push(`Diferencia preliminar frente al valor informado: $${(estimated-paid).toLocaleString("es-CO")}.`);return {estimated,difference:estimated-paid,formula,flags,factors,review:"Pendiente de revisión profesional",createdAt:new Date().toLocaleString("es-CO")}}
