function ensureCaseRelations(){state.cases=state.cases.map(item=>String(item.id||"").startsWith("CRM-")&&!item.createdByUsername?{...item,createdBy:state.user?.name||"",createdByUsername:state.user?.username||"",createdByDepartment:state.user?.department||"",visibilityDepartments:["Dirección General"]}:item)}
