function messagesView(){const unread=state.messages.filter(message=>message.fromUsername!==state.user.username&&!(message.readBy||[]).includes(state.user.username));return `<div class="messagesLayout"><section class="panel"><div class="panelHeader"><div><h2>Bandeja interna</h2><span class="muted">Mensajes dirigidos a tu departamento y enviados por ti</span></div><div class="messageActions"><button id="refreshMessages" class="secondary">↻ Actualizar</button><button id="newMessage" class="primary">+ Nuevo mensaje</button></div></div><div class="messageSummary"><span><strong>${unread.length}</strong> sin leer</span><span><strong>${state.messages.length}</strong> visibles</span></div><div class="messageList">${state.messages.length?state.messages.map(message=>{const isUnread=message.fromUsername!==state.user.username&&!(message.readBy||[]).includes(state.user.username);return `<button class="messageRow ${isUnread?"unread":""}" data-message-open="${esc(message.id)}"><span class="messageDot"></span><span class="messageRowMain"><strong>${esc(message.subject)}</strong><small>${esc(message.fromName)} · ${esc(message.fromDepartment)} → ${esc(message.toDepartment)}</small></span><span class="messageRowMeta"><small>${new Date(message.createdAt).toLocaleString("es-CO")}</small>${message.attachments?.length?`<small>📎 ${message.attachments.length}</small>`:""}</span></button>`}).join(""):`<div class="empty">Aún no hay mensajes internos.</div>`}</div></section><aside id="messageDetail" class="panel messageDetail"><div class="empty">Selecciona un mensaje para consultarlo.</div></aside></div>`}
