function effectiveAlert(c){if(c.status==="Facturado")return c.paymentDate?"":"Pendiente de pago";if(c.due){const due=new Date(`${c.due}T23:59:59`);const days=Math.ceil((due-new Date())/86400000);if(days<0)return `Vencido: ${c.due}`;if(days<=3)return `Próximo a vencer: ${c.due}`;}return c.alert||(c.status==="Recibido"?"Pendiente":"");}
function alerts(){return visibleCases().filter(c=>effectiveAlert(c));}
function requestState(c){const status=normalizedText(c.status),alert=normalizedText(effectiveAlert(c));if(status.includes("bloque")||alert.includes("bloque"))return {key:"blocked",label:"BLOQUEADO"};if(alert.includes("vencido")||alert.includes("crit"))return {key:"critical",label:"VENCIDO / CRÍTICO"};if(alert.includes("proximo a vencer"))return {key:"soon",label:"PRÓXIMO A VENCER"};if(status==="terminado"||status==="facturado"||status==="completado")return {key:"completed",label:"COMPLETADO"};if(status.includes("proceso")||status.includes("curso"))return {key:"processing",label:"EN PROCESO"};return {key:"pending",label:"PENDIENTE"}}
