function render(){currentUserLabel.textContent=state.user.name;const hasAssistant=assistantAvailable(),assistantNav=$("#assistantNav");if(assistantNav)assistantNav.hidden=!hasAssistant;[$("#dictateCaseNotes"),$("#dictateObservation")].forEach(button=>{if(button)button.hidden=!hasAssistant});[$("#caseVoiceStatus"),$("#observationVoiceStatus")].forEach(label=>{if(label)label.hidden=!hasAssistant});if(state.view==="assistant"&&!hasAssistant)state.view="dashboard";departmentScope.innerHTML=state.user.all?`<option value="all">Todos los departamentos</option>`+departments.map(d=>`<option>${d}</option>`).join(""): `<option>${departmentGroup(state.user.department)}</option>`;departmentScope.value=state.scope;const allowedDepartments=state.user.all?departments:[departmentGroup(state.user.department)];caseDepartment.innerHTML=allowedDepartments.map(d=>`<option>${d}</option>`).join("");updateResponsibleOptions();alertBadge.textContent=alerts().length;updateMessageBadge(); const titles={dashboard:"Resumen general",cases:"Casos y servicios",alerts:"Alertas pendientes",clients:"Clientes",prospects:"Prospectos QR",documents:"Gestión documental",tasks:"Tareas asignadas",messages:"Mensajes internos",assistant:"Asistente de control",admin:"Administración"};viewTitle.textContent=titles[state.view]; document.querySelectorAll(".navItem").forEach(b=>b.classList.toggle("active",b.dataset.view===state.view)); const views={dashboard:dashboard,cases:casesView,alerts:alertsView,clients:clientsView,prospects:prospectsView,documents:documentsView,tasks:tasksView,messages:messagesView,assistant:assistantView,admin:adminView};content.innerHTML=views[state.view]();if(state.view==="messages")populateMessageDepartments();if(state.view==="assistant"&&state.user.all)updateTaskResponsibleOptions();if(state.view==="admin"&&state.user.all){loadRecoveryRequests();loadActivity();}}
function populateMessageDepartments(){const select=$("#messageToDepartment");if(!select)return;const options=departments.filter(department=>state.user.all||!sameDepartment(department,state.user.department));if(state.user.all)options.unshift("Todos");select.innerHTML=options.map(department=>`<option value="${esc(department)}">${esc(department)}</option>`).join("");}
function dashboard(){const cs=visibleCases(),as=alerts();const summary=state.user.all?`<div class="panel departmentPanel"><div class="panelHeader"><h2>Carga por departamento</h2><span class="muted">casos · alertas</span></div><div class="departmentGrid">${departments.map(d=>{const rows=state.cases.filter(c=>sameDepartment(c.department,d)),pending=rows.filter(c=>effectiveAlert(c));return `<div class="departmentCard"><strong>${esc(d)}</strong><span>${rows.length} casos</span><b>${pending.length} alertas</b></div>`}).join("")}</div></div>`:"";const stateKeys=[{key:"pending",label:"Pendientes"},{key:"processing",label:"En proceso"},{key:"soon",label:"Próximos a vencer"},{key:"critical",label:"Críticos"},{key:"completed",label:"Completados"},{key:"blocked",label:"Bloqueados"}];const noContact=cs.filter(c=>!c.identification||!(c.contact||c.phone||c.email)).length;const statusPanel=`<div class="panel"><div class="panelHeader"><h2>Estado de la operación</h2><span class="muted">${cs.filter(c=>!c.responsible).length} sin responsable</span></div><div class="statusGrid visualStatusGrid">${stateKeys.map(item=>`<div class="statusCard state-${item.key}"><strong>${cs.filter(c=>requestState(c).key===item.key).length}</strong><span>${item.label}</span></div>`).join("")}<div class="statusCard state-neutral"><strong>${noContact}</strong><span>Datos incompletos</span></div></div></div>`;const legend=`<div class="statusLegend">${stateKeys.map(item=>`<span class="stateBadge ${item.key}"><i></i>${item.label.toUpperCase()}</span>`).join("")}</div>`;return `<div class="dashboardWelcome"><div><small>PANEL DE CONTROL</small><h2>Seguimiento operativo</h2><p>Prioridades, vencimientos y avance de las solicitudes.</p></div>${legend}</div><div class="stats"><div class="stat accentBlue"><small>Casos visibles</small><strong>${cs.length}</strong></div><div class="stat accentOrange"><small>Alertas activas</small><strong>${as.length}</strong></div><div class="stat accentCyan"><small>En proceso</small><strong>${cs.filter(c=>requestState(c).key==="processing").length}</strong></div><div class="stat accentGreen"><small>Completados</small><strong>${cs.filter(c=>requestState(c).key==="completed").length}</strong></div></div><div class="notice">Regla operativa: un caso no puede pasar a “Facturado” hasta completar la revisión de Recursos humanos.</div>${summary}${statusPanel}<div class="panel"><div class="panelHeader"><h2>Alertas que requieren atención</h2><button class="textButton" data-view="alerts">Ver todas</button></div>${alertRows(as.slice(0,6))}</div>`}
function alertRows(rows){return rows.length?`<div class="alertList">${rows.map(c=>{const a=effectiveAlert(c);return `<div class="alertRow"><div><strong>${esc(c.client)}</strong><small>${esc(c.service)}</small></div><div>${esc(departmentGroup(c.department))}</div><div>${stateBadge(c)}<small class="alertDetail">${esc(a)}</small></div><div>${esc(c.status)}</div><button class="textButton" data-open="${c.id}">Abrir</button></div>`}).join("")}</div>`:`<div class="empty">No hay alertas para este perfil.</div>`}
function searchCases(list){const term=(document.getElementById("globalSearch")?.value||document.getElementById("caseSearch")?.value||"").toLowerCase().trim();return term?list.filter(c=>`${c.client} ${c.service} ${c.id} ${c.department} ${c.identification||""} ${c.phone||""} ${c.email||""}`.toLowerCase().includes(term)):list}
function casesView(){const cs=searchCases(visibleCases());return `<div class="panel"><div class="tableTools"><input id="caseSearch" value="${esc(document.getElementById("globalSearch")?.value||"")}" placeholder="Buscar cliente, NIT, cédula o caso..."><button class="primary" id="newCaseInline">+ Nuevo caso</button></div><div id="caseRows" class="caseList">${caseRows(cs)}</div></div>`}
function caseRows(cs){return cs.length?cs.map(c=>{const a=effectiveAlert(c);return `<div class="caseRow"><div><strong>${esc(c.client)}</strong><small>${esc(c.id)} · ${c.folderPath?"📁 carpeta enlazada":"sin carpeta enlazada"}</small></div><div><small>${esc(departmentGroup(c.department))}</small><br>${esc(c.service)}<small>Responsable: ${esc(c.responsible||"Sin asignar")}</small></div><div>${stateBadge(c)}</div><div><span class="pill ${requestState(c).key}">${esc(a||c.status)}</span></div><button class="textButton" data-open="${c.id}">Detalle</button></div>`}).join(""):`<div class="empty">No hay casos visibles para este departamento.</div>`}
function alertsView(){return `<div class="panel"><div class="panelHeader"><h2>Alertas separadas del seguimiento</h2><span class="muted">${alerts().length} activas</span></div>${alertRows(alerts())}</div>`}
function clientsView(){const names=[...new Set(visibleCases().map(c=>c.client))];return `<div class="panel"><div class="panelHeader"><h2>Clientes</h2><span class="muted">${names.length} registrados</span></div>${names.length?names.map(n=>`<div class="caseRow"><strong>${esc(n)}</strong><span class="muted">${visibleCases().filter(c=>c.client===n).length} caso(s)</span><span></span><span></span><button class="textButton" data-view="cases">Ver casos</button></div>`).join(""):`<div class="empty">Aún no hay clientes registrados.</div>`}</div>`}
function prospectStatus(prospect){const key=normalizedText(prospect.status);return `<span class="pill ${key.includes("convert")?"done":"pending"}">${esc(prospect.status||"Nuevo")}</span>`}
function prospectsView(){const rows=state.prospects||[];const synced=state.prospectsSyncedAt?new Date(state.prospectsSyncedAt).toLocaleString("es-CO"):"No sincronizado";return `<div class="panel"><div class="panelHeader"><div><h2>Prospectos QR</h2><span class="muted">Hoja “Prospectos” · última sincronización: ${esc(synced)}</span></div><button id="refreshProspects" class="secondary">↻ Actualizar</button></div><p class="notice">Los prospectos se consultan desde “BC Soluciones - Registro de prospectos QR”. El departamento se sugiere automáticamente según el servicio solicitado.</p><div class="caseList">${rows.length?rows.map(prospect=>`<div class="caseRow prospectRow"><div><strong>${esc(prospect.fullName||"Sin nombre")}</strong><small>${esc(prospect.email||prospect.phone||"Sin contacto")} · ${esc(prospect.qrCode||prospect.siteId||prospect.key)}</small></div><div><small>Servicio solicitado</small><br>${esc(prospect.service||"No especificado")}</div><div><small>Departamento sugerido</small><br><strong>${esc(prospect.routingDepartment)}</strong></div><div>${prospectStatus(prospect)}${prospect.convertedCaseId?`<small>${esc(prospect.convertedCaseId)}</small>`:""}</div><button class="textButton" data-prospect-convert="${esc(prospect.key)}" ${prospect.convertedCaseId?"disabled":""}>${prospect.convertedCaseId?"Convertido":"Crear cliente"}</button></div>`).join(""):`<div class="empty">No hay prospectos disponibles para este perfil.</div>`}</div></div>`}
function beginProspectConversion(key){const prospect=(state.prospects||[]).find(item=>item.key===key);if(!prospect||prospect.convertedCaseId)return;caseForm.reset();caseForm.dataset.prospectKey=prospect.key;caseForm.elements.client.value=prospect.fullName||"";caseForm.elements.service.value=prospect.service||"Solicitud recibida desde QR";caseForm.elements.phone.value=prospect.phone||"";caseForm.elements.email.value=prospect.email||"";caseForm.elements.department.value=prospect.routingDepartment;caseForm.elements.notes.value=[`Prospecto captado desde QR${prospect.qrCode?` (${prospect.qrCode})`:""}.`,prospect.notes].filter(Boolean).join(" ");updateResponsibleOptions();caseModal.classList.add("visible")}
function documentsView(){const cs=visibleCases();const linked=cs.filter(c=>c.folderPath),missing=cs.filter(c=>!c.folderPath);return `<div class="stats"><div class="stat"><small>Casos visibles</small><strong>${cs.length}</strong></div><div class="stat"><small>Con carpeta enlazada</small><strong>${linked.length}</strong></div><div class="stat"><small>Sin carpeta enlazada</small><strong>${missing.length}</strong></div><div class="stat"><small>Alertas documentales</small><strong>${cs.filter(c=>String(c.pending||c.alert||"").toLowerCase().includes("document")||String(c.pending||"").trim()).length}</strong></div></div><div class="panel"><div class="panelHeader"><h2>Índice documental</h2><span class="muted">Las rutas se muestran para abrirlas desde el equipo donde están almacenadas.</span></div><div class="caseList">${cs.length?cs.map(c=>`<div class="caseRow"><div><strong>${esc(c.client)}</strong><small>${esc(c.id)}</small></div><div><small>${esc(departmentGroup(c.department))}</small><br>${esc(c.service)}</div><div class="documentPath">${esc(c.folderPath||"Sin carpeta enlazada")}</div><div><span class="pill ${c.folderPath?"done":"pending"}">${c.folderPath?"Carpeta disponible":"Revisar carpeta"}</span></div><button class="textButton" data-copy="${esc(c.folderPath||"")}" ${c.folderPath?"":"disabled"}>Copiar ruta</button><button class="textButton" data-open="${c.id}">Detalle</button></div>`).join(""):`<div class="empty">No hay documentos para este perfil.</div>`}</div></div>`}
function assistantView(){if(!assistantAvailable())return `<div class="panel"><div class="empty">Este asistente está disponible para Dirección General y Departamento General.</div></div>`;const assignment=state.user.all?`<section class="taskAssignment"><div class="panelHeader"><div><h3>Asignar tarea por instrucción</h3><span class="muted">Dicta la instrucción y asígnala al departamento responsable.</span></div><span class="assistantMark">✓</span></div><form id="taskForm" class="formGrid"><label class="fullField">Instrucción de la tarea<textarea id="taskDescription" rows="3" placeholder="Ejemplo: Revisar los soportes tributarios de Adolfo Arias y reportar novedades"></textarea></label><div class="voiceFieldAction fullField"><button id="taskVoice" type="button" class="secondary">🎙 Dictar tarea</button><small id="taskVoiceStatus" class="muted">El dictado se agregará a la instrucción.</small></div><label>Departamento<select id="taskDepartment" required>${departments.map(d=>`<option>${esc(d)}</option>`).join("")}</select></label><label>Responsable<select id="taskResponsible" required></select></label><label>Fecha límite<input id="taskDue" type="date"></label><label>Prioridad<select id="taskPriority"><option>Alta</option><option selected>Media</option><option>Baja</option></select></label><div class="formActions fullField"><button class="primary">Asignar tarea</button></div></form><small id="taskFormMessage" class="taskFormMessage" role="status"></small></section>`:"";return `<div class="assistantLayout"><div class="panel assistantPanel"><div class="assistantIntro"><span class="assistantMark">✦</span><div><h2>Asistente de control y monitoreo</h2><p>Consulta la operación visible para tu perfil o dicta información en español.</p></div></div><form id="assistantForm" class="assistantComposer"><textarea id="assistantPrompt" placeholder="Ejemplo: Muéstrame los casos vencidos y sin responsable"></textarea><div class="assistantComposerActions"><button id="assistantVoice" type="button" class="secondary">🎙 Iniciar dictado</button><button class="primary">Consultar</button><small id="assistantVoiceStatus" class="muted">Micrófono inactivo</small></div></form><div class="assistantQuickActions"><button class="secondary" data-assistant-query="resumen ejecutivo">Resumen ejecutivo</button><button class="secondary" data-assistant-query="alertas críticas">Alertas críticas</button><button class="secondary" data-assistant-query="estado de cartera">Cartera</button><button class="secondary" data-assistant-query="carga por departamento">Carga por departamento</button><button class="secondary" data-assistant-query="control documental">Documentos</button></div><div id="assistantResponse" class="assistantResponse"><h3>¿En qué te apoyo?</h3>Puedes escribir o dictar una consulta. El asistente analizará únicamente los casos permitidos para tu perfil.</div>${assignment}</div><aside class="panel assistantSide"><h3>Consultas disponibles</h3><ul class="assistantExamples"><li>Casos vencidos o próximos a vencer.</li><li>Facturas pendientes y estados de pago.</li><li>Casos sin responsable o sin carpeta.</li><li>Carga operativa por departamento.</li><li>Búsqueda por cliente, caso o servicio.</li></ul><div class="assistantPrivacy">Los casos y documentos no se envían a servicios de inteligencia artificial externos. El navegador gestiona el reconocimiento de voz según sus permisos y su servicio de dictado.</div></aside></div>`}

function updateTaskResponsibleOptions(){const department=$("#taskDepartment"),responsible=$("#taskResponsible");if(!department||!responsible)return;const matches=users.filter(user=>sameDepartment(user.department,department.value));responsible.innerHTML=matches.map(user=>`<option value="${esc(user.name)}">${esc(user.name)}</option>`).join("")||`<option value="">Sin responsable disponible</option>`}
function reportPeriodStart(){const date=new Date();date.setHours(0,0,0,0);const day=date.getDay()||7;date.setDate(date.getDate()-day+1);return date}
function weeklyReportRows(){const start=reportPeriodStart();return visibleTasks().filter(task=>task.status!=="Completada"||new Date(task.updatedAt||task.createdAt||0)>=start)}
function generateWeeklyTaskReport(){const rows=weeklyReportRows(),completed=rows.filter(task=>task.status==="Completada").length,pending=rows.filter(task=>task.status!=="Completada").length,progress=rows.length?Math.round(completed/rows.length*100):0,scope=state.user.all?(state.scope==="all"?"Todos los departamentos":state.scope):state.user.department,grouped=[...new Set(rows.map(task=>task.department))].map(department=>({department,count:rows.filter(task=>task.department===department).length,done:rows.filter(task=>task.department===department&&task.status==="Completada").length})).sort((a,b)=>b.count-a.count),bar=value=>`<span class="reportBar"><i style="width:${value}%"></i></span>`;const popup=window.open("","_blank","width=1000,height=800");if(!popup){alert("Permite las ventanas emergentes para generar el informe PDF.");return}popup.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Informe semanal de tareas · BC Soluciones</title><style>body{font:14px Arial,sans-serif;color:#24313d;margin:34px}h1{color:#17324d;margin-bottom:4px}h2{color:#2f78c4;margin-top:28px}.meta{color:#687887;margin-bottom:22px}.cards{display:flex;gap:12px}.card{border:1px solid #dfe7ee;border-radius:8px;padding:14px;min-width:150px}.card strong{display:block;font-size:26px;margin-top:5px}.reportBar{display:inline-block;width:130px;height:8px;background:#e7eef4;border-radius:8px;vertical-align:middle}.reportBar i{display:block;height:100%;background:#2f78c4;border-radius:8px}table{border-collapse:collapse;width:100%;margin-top:12px}th,td{border:1px solid #dfe7ee;padding:8px;text-align:left;vertical-align:top}th{background:#eef5fb;color:#17324d}.status{font-weight:700}.footer{margin-top:28px;color:#687887;font-size:12px}@media print{body{margin:16mm}.noPrint{display:none}}</style></head><body><h1>Informe semanal de tareas</h1><div class="meta">BC Soluciones · Destino: Dirección General<br>Perfil: ${esc(state.user.name)} · Alcance: ${esc(scope)}<br>Periodo: ${reportPeriodStart().toLocaleDateString("es-CO")} a ${new Date().toLocaleDateString("es-CO")}</div><div class="cards"><div class="card">Tareas analizadas<strong>${rows.length}</strong></div><div class="card">Completadas<strong>${completed}</strong></div><div class="card">Pendientes<strong>${pending}</strong></div><div class="card">Avance<strong>${progress}%</strong></div></div><h2>Progreso por departamento</h2><table><thead><tr><th>Departamento</th><th>Tareas</th><th>Completadas</th><th>Avance</th></tr></thead><tbody>${grouped.map(item=>{const percentage=item.count?Math.round(item.done/item.count*100):0;return `<tr><td>${esc(item.department)}</td><td>${item.count}</td><td>${item.done}</td><td>${bar(percentage)} ${percentage}%</td></tr>`}).join("")||`<tr><td colspan="4">No hay tareas en el periodo.</td></tr>`}</tbody></table><h2>Detalle de actividades</h2><table><thead><tr><th>Tarea</th><th>Departamento</th><th>Responsable</th><th>Estado</th><th>Prioridad</th><th>Vencimiento</th></tr></thead><tbody>${rows.map(task=>`<tr><td>${esc(task.title)}<br><small>${esc(task.description||"")}</small></td><td>${esc(task.department)}</td><td>${esc(task.responsible)}</td><td class="status">${esc(task.status)}</td><td>${esc(task.priority)}</td><td>${esc(task.due||"Sin fecha")}</td></tr>`).join("")||`<tr><td colspan="6">No hay actividades registradas.</td></tr>`}</tbody></table><p class="footer">Generado el ${new Date().toLocaleString("es-CO")}. Este informe puede guardarse como PDF desde la ventana de impresión.</p></body></html>`);popup.document.close();popup.focus();setTimeout(()=>popup.print(),350)}

function normalizedText(value){return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase()}
function money(value){return new Intl.NumberFormat("es-CO",{style:"currency",currency:"COP",maximumFractionDigits:0}).format(Number(value)||0)}
function assistantAnswer(question){const query=normalizedText(question),rows=visibleCases(),activeAlerts=rows.filter(c=>effectiveAlert(c)),overdue=rows.filter(c=>normalizedText(effectiveAlert(c)).includes("vencido")),unassigned=rows.filter(c=>!c.responsible),withoutFolder=rows.filter(c=>!c.folderPath),portfolio=rows.filter(c=>c.status==="Facturado"&&!c.paymentDate||["por vencer","mora temprana","mora critica"].includes(normalizedText(c.paymentStatus)));const show=list=>list.slice(0,8).map(c=>`• ${c.client} (${c.id}) — ${c.department} — ${effectiveAlert(c)||c.status}`).join("\n")||"No se encontraron casos con ese criterio.";if(query.includes("abrir alertas")){state.view="alerts";render();return "Abrí la vista de alertas para continuar la revisión."}if(query.includes("nuevo caso")||query.includes("crear caso")){caseModal.classList.add("visible");return "Abrí el formulario de nuevo caso. Puedes usar el botón de dictado para registrar las observaciones."}if(query.includes("venc")||query.includes("critic")||query.includes("alert"))return `Alertas de atención prioritaria: ${overdue.length} casos vencidos y ${activeAlerts.length} alertas activas.\n\n${show(overdue.length?overdue:activeAlerts)}`;if(query.includes("cartera")||query.includes("pago")||query.includes("factur")||query.includes("mora")){const total=portfolio.reduce((sum,c)=>sum+(Number(c.value)||0),0);return `Cartera por revisar: ${portfolio.length} casos. Valor registrado: ${money(total)}.\n\n${show(portfolio)}`;}if(query.includes("carga")||query.includes("depart")){const grouped=[...new Set(rows.map(c=>c.department))].map(department=>({department,count:rows.filter(c=>c.department===department).length,alerts:rows.filter(c=>c.department===department&&effectiveAlert(c)).length})).sort((a,b)=>b.count-a.count);return `Carga operativa visible:\n\n${grouped.map(x=>`• ${x.department}: ${x.count} casos, ${x.alerts} alertas`).join("\n")||"No hay casos visibles."}`;}if(query.includes("document")||query.includes("carpeta"))return `Control documental: ${rows.length-withoutFolder.length} casos con carpeta enlazada y ${withoutFolder.length} sin carpeta.\n\n${show(withoutFolder)}`;if(query.includes("responsable")||query.includes("asign"))return `Hay ${unassigned.length} casos sin responsable.\n\n${show(unassigned)}`;const terms=query.replace(/buscar|cliente|caso|servicio|consultar/g," ").split(/\s+/).filter(term=>term.length>2);if(terms.length){const found=rows.filter(c=>terms.every(term=>normalizedText(`${c.client} ${c.id} ${c.service} ${c.department} ${c.responsible||""}`).includes(term)));if(found.length)return `Encontré ${found.length} coincidencia(s):\n\n${show(found)}`;}return `Resumen ejecutivo: ${rows.length} casos visibles, ${rows.filter(c=>c.status==="En proceso").length} en proceso, ${activeAlerts.length} alertas, ${overdue.length} vencidos, ${unassigned.length} sin responsable y ${withoutFolder.length} sin carpeta enlazada.`}
function runAssistant(question){const response=$("#assistantResponse");if(!response)return;const value=String(question||"").trim();if(!value){response.textContent="Escribe o dicta una consulta para continuar.";return}response.textContent=assistantAnswer(value)}
function calendarView(){const rows=state.calendar.slice().sort((a,b)=>(a.date+' '+(a.time||'')).localeCompare(b.date+' '+(b.time||'')));let out='<div class="panel"><div class="panelHeader"><div><h2>Agenda y alertas</h2><span class="muted">Tareas y reuniones programadas por Dirección General</span></div><button id="refreshCalendar" class="secondary">↻ Actualizar</button></div>';if(state.user.all)out+='<form id="calendarForm" class="formGrid"><label>Tipo<select name="type"><option>Tarea</option><option>Reunión</option></select></label><label>Título<input name="title" required maxlength="180" placeholder="Ej. Revisión mensual SG-SST"></label><label>Fecha<input name="date" type="date" required></label><label>Hora<input name="time" type="time"></label><label>Departamento<select name="department"><option>Todos</option>'+departments.filter(d=>d!=="Dirección General").map(d=>'<option>'+esc(d)+'</option>').join('')+'</select></label><label>Perfil<select name="username"><option value="">Todos los perfiles del departamento</option>'+users.filter(u=>!u.all).map(u=>'<option value="'+esc(u.username)+'">'+esc(u.name)+' · '+esc(u.department)+'</option>').join('')+'</select></label><label>Prioridad<select name="priority"><option>Alta</option><option selected>Media</option><option>Baja</option></select></label><label class="fullField">Detalle<textarea name="description" rows="2" placeholder="Objetivo, preparación o evidencia esperada"></textarea></label><div class="formActions fullField"><button class="primary">Programar actividad</button></div></form>';else out+='<p class="muted">Dirección General programa las actividades. Este perfil puede actualizar el estado de las actividades asignadas.</p>';out+='</div><div class="panel"><div class="calendarList">';out+=rows.length?rows.map(item=>{const alert=calendarAlert(item);return '<div class="calendarRow '+(alert?'calendarAlert':'')+'"><div><small>'+esc(item.type)+' · '+esc(item.date)+' '+esc(item.time||'')+'</small><strong>'+esc(item.title)+'</strong><span>'+esc(item.description||'')+'</span></div><div><span class="pill '+(item.status==="Completada"?"done":alert?"critical":"processing")+'">'+esc(alert||item.status)+'</span><small>'+esc(item.department)+(item.username?' · '+esc(item.username):'')+'</small></div><select data-calendar-status="'+esc(item.id)+'"><option '+(item.status==="Pendiente"?"selected":"")+'>Pendiente</option><option '+(item.status==="En proceso"?"selected":"")+'>En proceso</option><option '+(item.status==="Completada"?"selected":"")+'>Completada</option><option '+(item.status==="Cancelada"?"selected":"")+'>Cancelada</option></select></div>'}).join(''):'<div class="empty">No hay tareas ni reuniones programadas para este perfil.</div>';return out+'</div></div>'}
function companyView(){const p=state.companyProfile||{},val=key=>esc(Array.isArray(p[key])?p[key].join(', '):(p[key]||''));let out='<div class="panel"><div class="panelHeader"><div><h2>Perfil de BCSoluciones</h2><span class="muted">Base de información para el piloto SG-SST y Recursos Humanos</span></div><span class="pill processing">'+(p.workers||0)+' trabajadores · '+(p.contractors||0)+' contratistas</span></div>';if(!state.user.all)return out+'<p class="muted">Solo Dirección General puede editar este perfil.</p></div>';out+='<form id="companyProfileForm" class="formGrid"><label>Razón social<input name="legalName" value="'+val('legalName')+'"></label><label>Actividad económica<input name="economicActivity" value="'+val('economicActivity')+'"></label><label>Sedes<input name="sites" type="number" min="1" value="'+(p.sites||1)+'"></label><label>Trabajadores<input name="workers" type="number" min="0" value="'+(p.workers||0)+'"></label><label>Contratistas<input name="contractors" type="number" min="0" value="'+(p.contractors||0)+'"></label><label>Modalidades<input name="workModes" value="'+val('workModes')+'" placeholder="Presencial, Remoto, En campo"></label><label class="fullField">Cargos<textarea name="positions" rows="2">'+val('positions')+'</textarea></label><label class="fullField">Equipos y herramientas<textarea name="equipment" rows="2">'+val('equipment')+'</textarea></label><label class="fullField">Actividades realizadas<textarea name="activities" rows="2">'+val('activities')+'</textarea></label><label class="fullField">Accidentes e incidentes<textarea name="accidents" rows="2">'+val('accidents')+'</textarea></label><label class="fullField">Ausentismo<textarea name="absenteeism" rows="2">'+val('absenteeism')+'</textarea></label><label class="fullField">Afiliaciones<textarea name="affiliations" rows="2">'+val('affiliations')+'</textarea></label><label class="fullField">Proveedores<textarea name="providers" rows="2">'+val('providers')+'</textarea></label><label class="fullField">Salud ocupacional<textarea name="occupationalHealth" rows="2">'+val('occupationalHealth')+'</textarea></label><label class="fullField">Contratación y nómina<textarea name="hiring" rows="2">'+val('hiring')+'</textarea></label><label class="fullField">Permisos y retiros<textarea name="permissions" rows="2">'+val('permissions')+'</textarea></label><label class="fullField">Políticas y documentos<textarea name="internalPolicies" rows="2">'+val('internalPolicies')+'</textarea></label><div class="formActions fullField"><button class="primary">Guardar perfil de empresa</button></div></form></div>';return out}
function startDictation(target,status){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){if(status)status.textContent="El dictado requiere Chrome o Edge con permiso de micrófono.";return}if(activeRecognition){activeRecognition.stop();activeRecognition=null}const recognition=new Recognition();activeRecognition=recognition;recognition.lang="es-CO";recognition.continuous=false;recognition.interimResults=true;const initial=target.value.trim();recognition.onstart=()=>{if(status)status.textContent="Escuchando… habla ahora"};recognition.onresult=event=>{const transcript=[...event.results].map(result=>result[0].transcript).join(" ");target.value=`${initial}${initial?" ":""}${transcript}`};recognition.onerror=event=>{if(status)status.textContent=event.error==="not-allowed"?"Activa el permiso del micrófono para dictar.":"No se pudo reconocer el audio. Intenta nuevamente."};recognition.onend=()=>{activeRecognition=null;if(status&&!status.textContent.includes("permiso")&&!status.textContent.includes("pudo"))status.textContent="Dictado finalizado"};recognition.start()}
function adminView(){if(!state.user.all)return `<div class="panel"><div class="empty">Esta sección está disponible únicamente para Dirección General.</div></div>`;const options=users.map(u=>`<option value="${esc(u.username)}">${esc(u.username)} · ${esc(u.department)}</option>`).join("");return `<div class="panel"><div class="panelHeader"><h2>Recuperación de usuarios</h2><span class="muted">Solo Dirección General</span></div><p class="muted">Asigna una contraseña temporal después de verificar la identidad por el canal corporativo.</p><form id="adminResetForm" class="formGrid"><label>Usuario<select id="adminTarget">${options}</select></label><label>Nueva contraseña<input id="adminNewPassword" type="password" minlength="10" required></label><div class="formActions fullField"><button class="primary">Restablecer contraseña</button></div></form><h3>Solicitudes recientes</h3><div id="recoveryRequests" class="empty">Cargando solicitudes...</div><h3>Actividad reciente</h3><div id="activityLog" class="empty">Cargando actividad...</div></div>`}
let documentDbPromise;
function documentDb(){return documentDbPromise||(documentDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open("bc-soluciones-crm",1);request.onupgradeneeded=()=>request.result.createObjectStore("pdfs",{keyPath:"id",autoIncrement:true});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)}))}
async function listCaseDocuments(caseId){const db=await documentDb();return new Promise((resolve,reject)=>{const request=db.transaction("pdfs").objectStore("pdfs").getAll();request.onsuccess=()=>resolve(request.result.filter(x=>x.caseId===caseId));request.onerror=()=>reject(request.error)})}
async function saveCaseDocument(caseId,file){const db=await documentDb();return new Promise((resolve,reject)=>{const request=db.transaction("pdfs","readwrite").objectStore("pdfs").add({caseId,name:file.name,size:file.size,type:file.type,createdAt:new Date().toISOString(),blob:file});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function deleteCaseDocument(id){const db=await documentDb();return new Promise((resolve,reject)=>{const request=db.transaction("pdfs","readwrite").objectStore("pdfs").delete(id);request.onsuccess=resolve;request.onerror=()=>reject(request.error)})}
async function listFolderDocuments(caseId){const response=await fetch(`/api/local-folder/documents?caseId=${encodeURIComponent(caseId)}`,{cache:"no-store"});if(!response.ok)throw new Error("No fue posible leer la carpeta del cliente");return response.json()}
async function renderCaseDocuments(caseId){const target=$("#detailDocuments");if(!target)return;target.innerHTML=`<div class="empty">Consultando documentos del cliente...</div>`;try{const [localDocs,folderDocs]=await Promise.all([listCaseDocuments(caseId),listFolderDocuments(caseId)]);const localRows=localDocs.map(d=>`<div class="documentItem"><span>📄 ${esc(d.name)} <small>(incorporado al CRM)</small></span><small>${Math.ceil(d.size/1024)} KB</small><button class="textButton" data-pdf-open="${d.id}">Ver PDF</button><button class="textButton danger" data-pdf-delete="${d.id}">Eliminar</button></div>`);const folderRows=folderDocs.files.map(d=>`<div class="documentItem"><span>📄 ${esc(d.name)} <small>(carpeta del cliente)</small></span><small>${Math.ceil(d.size/1024)} KB</small><button class="textButton" data-folder-pdf-open="${esc(encodeURIComponent(d.path))}">Ver PDF</button></div>`);target.innerHTML=[...localRows,...folderRows].join("")||`<div class="empty">No hay PDF asociados ni PDF encontrados en la carpeta del cliente.</div>`;if(folderDocs.folder)target.insertAdjacentHTML("afterbegin",`<small class="documentFolder">Carpeta consultada: ${esc(folderDocs.folder)}</small>`)}catch{target.innerHTML=`<div class="empty">No fue posible leer la carpeta del cliente. Verifica que la carpeta esté disponible en el equipo.</div>`}}
function openCase(id){const c=state.cases.find(x=>x.id===id);if(!c)return;selectedCaseId=id;detailTitle.textContent=`${c.client} · ${c.id}`;detailStatus.value=["Recibido","En proceso","Terminado","Facturado"].includes(c.status)?c.status:"Recibido";detailDelivery.value=c.delivery||"";detailInvoice.value=c.invoice||"";detailPayment.value=c.paymentDate||"";detailValue.value=c.value||"";detailPaymentStatus.value=c.paymentStatus||"Al día";detailQualityStatus.value=c.qualityStatus||"Pendiente";detailPending.value=c.pending||"";detailContent.innerHTML=`<div class="detailState">${stateBadge(c)}<span>${esc(effectiveAlert(c)||c.status)}</span></div><div class="detailGrid"><div><small>Departamento</small><strong>${esc(c.department)}</strong></div><div><small>Responsable</small><strong>${esc(c.responsible||"Sin asignar")}</strong></div><div><small>Servicio</small><strong>${esc(c.service)}</strong></div><div><small>Identificación</small><strong>${esc(c.identification||"No registrada")}</strong></div><div><small>Contacto</small><strong>${esc(c.contact||c.phone||c.email||"No registrado")}</strong></div><div><small>Entrega</small><strong>${esc(c.delivery||"No registrada")}</strong></div><div><small>Factura</small><strong>${esc(c.invoice||"No registrada")}</strong></div><div><small>Pago</small><strong>${esc(c.paymentDate||"No registrado")}</strong></div><div><small>Valor</small><strong>${esc(c.value||"No registrado")}</strong></div><div><small>Estado de pago</small><strong>${esc(c.paymentStatus||"Al día")}</strong></div><div><small>Documentos faltantes</small><strong>${esc(c.pending||"Ninguno registrado")}</strong></div><div><small>Alerta</small><strong>${esc(effectiveAlert(c)||"Sin alerta")}</strong></div><div><small>Carpeta</small><strong>${esc(c.folderPath||"No enlazada")}</strong></div></div><h3>Observaciones</h3>${(c.observations||[]).length?`<div class="observations">${c.observations.map(o=>`<div class="observation"><strong>${esc(o.by)}</strong><small>${esc(o.at)}</small><p>${esc(o.text)}</p></div>`).join("")}</div>`:`<div class="empty">Aún no hay observaciones.</div>`}`;observationText.value="";detailModal.classList.add("visible");renderCaseDocuments(id);}
document.addEventListener("click",e=>{const prospect=e.target.closest("[data-prospect-convert]");if(prospect&&!prospect.disabled){beginProspectConversion(prospect.dataset.prospectConvert);return}const copy=e.target.closest("[data-copy]");if(copy&&!copy.disabled){const value=copy.dataset.copy;navigator.clipboard?.writeText(value).then(()=>{const old=copy.textContent;copy.textContent="Ruta copiada";setTimeout(()=>copy.textContent=old,1200)}).catch(()=>alert(value));return}const v=e.target.closest("[data-view]");if(v){state.view=v.dataset.view;render();return}const o=e.target.closest("[data-open]");if(o){openCase(o.dataset.open);const opened=state.cases.find(item=>item.id===o.dataset.open);if(opened?.status==="Bloqueado")detailStatus.value="Bloqueado"}const close=e.target.closest("[data-close]");if(close)$("#"+close.dataset.close).classList.remove("visible");if(e.target.id==="newCase"||e.target.id==="newCaseInline"){delete caseForm.dataset.prospectKey;caseForm.reset();caseModal.classList.add("visible");}});
document.addEventListener("click",async e=>{if(!e.target.closest("#refreshProspects"))return;await loadProspects();if(state.view==="prospects")render()});
function closePdfPreview(){const frame=$("#pdfFrame"),modal=$("#pdfModal"),link=$("#openPdfNewTab");if(frame){frame.src="about:blank";if(frame.dataset.objectUrl)URL.revokeObjectURL(frame.dataset.objectUrl);delete frame.dataset.objectUrl}if(link)link.href="#";if(modal)modal.classList.remove("visible")}
function openPdfPreview({url,name,pathLabel,objectUrl=false}){const frame=$("#pdfFrame"),modal=$("#pdfModal"),title=$("#pdfModalTitle"),route=$("#pdfModalPath"),link=$("#openPdfNewTab"),loading=$("#pdfLoading");if(!frame||!modal)return;closePdfPreview();title.textContent=name||"Vista previa del PDF";route.textContent=pathLabel||"Documento incorporado al CRM";route.title=pathLabel||"Documento incorporado al CRM";if(objectUrl)frame.dataset.objectUrl=url;frame.onload=()=>loading?.classList.add("hidden");if(loading){loading.textContent="Cargando documento…";loading.classList.remove("hidden")}frame.src=url;if(link)link.href=url;modal.classList.add("visible")}
document.addEventListener("click",async e=>{const folderOpen=e.target.closest("[data-folder-pdf-open]");if(folderOpen){const encodedPath=folderOpen.dataset.folderPdfOpen;const decodedPath=decodeURIComponent(encodedPath);openPdfPreview({url:`/api/local-folder/pdf?caseId=${encodeURIComponent(selectedCaseId)}&path=${encodedPath}`,name:folderOpen.closest(".documentItem")?.querySelector("span")?.childNodes[0]?.textContent?.replace("📄","").trim()||"Documento PDF",pathLabel:`MASTER\\${decodedPath}`});return}const open=e.target.closest("[data-pdf-open]");if(open){const docs=await listCaseDocuments(selectedCaseId);const doc=docs.find(x=>String(x.id)===open.dataset.pdfOpen);if(doc){const url=URL.createObjectURL(doc.blob);openPdfPreview({url,name:doc.name,pathLabel:"Documento incorporado al CRM",objectUrl:true})}return}if(e.target.closest("#closePdfModal")){closePdfPreview();return}if(e.target.id==="pdfModal"){closePdfPreview();return}const remove=e.target.closest("[data-pdf-delete]");if(remove&&confirm("¿Eliminar este PDF del caso?")){await deleteCaseDocument(Number(remove.dataset.pdfDelete));renderCaseDocuments(selectedCaseId);}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#pdfModal")?.classList.contains("visible"))closePdfPreview()});
document.addEventListener("submit",e=>{if(e.target.id!=="assistantForm")return;e.preventDefault();runAssistant($("#assistantPrompt")?.value)});
document.addEventListener("submit",async e=>{if(e.target.id!=="taskForm")return;e.preventDefault();if(!state.user?.all)return;const description=$("#taskDescription")?.value.trim()||"";const department=$("#taskDepartment")?.value||"";const responsible=$("#taskResponsible")?.value||"";if(!description||!department||!responsible){$("#taskFormMessage").textContent="Completa la instrucción, el departamento y el responsable.";return}const payload={title:description.split(/[.!?\n]/)[0].trim().slice(0,180)||"Tarea operativa",description,department,responsible,due:$("#taskDue")?.value||"",priority:$("#taskPriority")?.value||"Media"};try{let created;if(apiMode){const response=await fetch("/api/tasks",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||"No fue posible asignar la tarea");created=await response.json()}else{created={...payload,id:`TASK-${Date.now().toString().slice(-8)}`,status:"Pendiente",createdBy:state.user.name,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}state.tasks.unshift(created);localStorage.setItem("bcTasks",JSON.stringify(state.tasks));e.target.reset();updateTaskResponsibleOptions();$("#taskFormMessage").textContent=`Tarea asignada a ${responsible}. Ahora es visible para ${department}.`;render()}catch(error){$("#taskFormMessage").textContent=error.message||"No fue posible asignar la tarea."}});
document.addEventListener("change",async e=>{if(e.target.id==="taskDepartment"){updateTaskResponsibleOptions();return}const select=e.target.closest("[data-task-status]");if(!select)return;const task=state.tasks.find(item=>item.id===select.dataset.taskStatus);if(!task)return;const previous=task.status;task.status=select.value;task.updatedAt=new Date().toISOString();try{if(apiMode){const response=await fetch(`/api/tasks/${encodeURIComponent(task.id)}`,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({status:task.status})});if(!response.ok)throw new Error()}localStorage.setItem("bcTasks",JSON.stringify(state.tasks));render()}catch{task.status=previous;select.value=previous;alert("No fue posible actualizar el estado de la tarea.")}});
document.addEventListener("click",e=>{const quick=e.target.closest("[data-assistant-query]");if(quick){const prompt=$("#assistantPrompt");if(prompt)prompt.value=quick.dataset.assistantQuery;runAssistant(quick.dataset.assistantQuery);return}if(e.target.closest("#assistantVoice")){startDictation($("#assistantPrompt"),$("#assistantVoiceStatus"));return}if(e.target.closest("#dictateCaseNotes")){startDictation(caseForm.elements.notes,$("#caseVoiceStatus"));return}if(e.target.closest("#dictateObservation")){startDictation(observationText,$("#observationVoiceStatus"));return}});
document.addEventListener("click",e=>{if(e.target.closest("#taskVoice")){startDictation($("#taskDescription"),$("#taskVoiceStatus"));return}if(e.target.closest("#weeklyTaskReport")){generateWeeklyTaskReport();return}if(e.target.closest("#taskDepartment"))updateTaskResponsibleOptions()});
document.addEventListener("input",e=>{if(e.target.id!=="caseSearch"&&e.target.id!=="globalSearch")return;if(e.target.id==="globalSearch"&&state.view!=="cases"){state.view="cases";render();return}const term=e.target.value.toLowerCase().trim();const filtered=visibleCases().filter(c=>`${c.client} ${c.service} ${c.id} ${c.department} ${c.identification||""} ${c.phone||""} ${c.email||""}`.toLowerCase().includes(term));const target=$("#caseRows");if(target)target.innerHTML=caseRows(filtered);});
exportReport.onclick=()=>{const columns=["ID","Cliente","Departamento","Servicio","Responsable","Estado","Fecha límite","Fecha de entrega","Factura","Fecha de pago","Alerta","Identificación","Contacto","Documentos faltantes","Carpeta","Observaciones"];const lines=[columns,...visibleCases().map(c=>[c.id,c.client,c.department,c.service,c.responsible||"",c.status,c.due||"",c.delivery||"",c.invoice||"",c.paymentDate||"",effectiveAlert(c),c.identification||"",c.contact||c.phone||c.email||"",c.pending||"",c.folderPath||"",(c.observations||[]).map(o=>`${o.by}: ${o.text}`).join(" | ")])].map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(","));const blob=new Blob(["\ufeff"+lines.join("\n")],{type:"text/csv;charset=utf-8"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`reporte-bc-soluciones-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(link.href);};
exportBackup.onclick=async()=>{try{const scope=state.user?.all?"Todos los departamentos":departmentGroup(state.user?.department);const response=apiMode?await fetch("/api/backup"):new Response(JSON.stringify({generatedAt:new Date().toISOString(),scope,cases:visibleCases()},null,2),{headers:{"content-type":"application/json"}});if(!response.ok)throw new Error();const blob=await response.blob();const link=document.createElement("a");link.href=URL.createObjectURL(blob);const suffix=normalizedText(scope).replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");link.download=`bc-soluciones-backup-${suffix}-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(link.href)}catch{alert("No fue posible generar el respaldo del departamento.")}};
refreshData.onclick=async()=>{if(!apiMode){await loadTasks();render();return}try{const response=await fetch("/api/cases");if(!response.ok)throw new Error();state.cases=await response.json();await Promise.all([loadTasks(),loadProspects()]);localStorage.setItem("bcCases",JSON.stringify(state.cases));render()}catch{alert("No fue posible actualizar los datos.")}};
async function login(){const user=users[Number(userSelect.value)];const password=passwordInput.value;if(apiAvailable){try{const response=await fetch("/api/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({username:user.username,password})});if(!response.ok){loginError.textContent="Usuario o contraseña incorrectos.";return}const remoteUser=await response.json();const casesResponse=await fetch("/api/cases");if(!casesResponse.ok){loginError.textContent="No fue posible cargar los casos.";return}state.cases=await casesResponse.json();apiMode=true;state.user={...user,...remoteUser};await loadTasks();await loadMessages();await loadProspects();}catch{loginError.textContent="No fue posible conectar con el servidor.";return}}else{if(password!==user.password){loginError.textContent="Usuario o contraseña incorrectos.";return}state.user=user;await loadTasks()}loginError.textContent="";passwordInput.value="";state.scope=state.user.all?"all":state.user.department;loginModal.classList.remove("visible");render()}
async function logout(){if(apiMode){try{await fetch("/api/logout",{method:"POST"})}catch{}}state.user=null;apiMode=false;loginModal.classList.add("visible");}
enterApp.onclick=login;forgotPassword.onclick=()=>{loginModal.classList.remove("visible");recoveryMessage.textContent="";recoveryModal.classList.add("visible")};changePassword.onclick=()=>{passwordMessage.textContent="";passwordForm.reset();passwordModal.classList.add("visible")};switchUser.onclick=()=>{if(apiMode)logout();else loginModal.classList.add("visible")};document.querySelector("#logout").onclick=logout;departmentScope.onchange=e=>{if(state.user.all)state.scope=e.target.value;render()};caseDepartment.onchange=updateResponsibleOptions;caseForm.onsubmit=async e=>{e.preventDefault();if(caseForm.dataset.prospectKey&&apiMode){const f=new FormData(caseForm);try{const response=await fetch("/api/prospects/convert",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({prospectKey:caseForm.dataset.prospectKey,department:f.get("department"),responsible:f.get("responsible"),due:f.get("due"),notes:f.get("notes")})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No fue posible convertir el prospecto");state.cases.unshift(data.case);state.prospects=state.prospects.map(item=>item.key===caseForm.dataset.prospectKey?{...item,...data.prospect}:item);delete caseForm.dataset.prospectKey;caseForm.reset();caseModal.classList.remove("visible");state.view="cases";render();return}catch(error){alert(error.message);return}}const f=new FormData(caseForm);const item={id:`CRM-${Date.now().toString().slice(-6)}`,client:f.get("client"),department:f.get("department"),responsible:f.get("responsible"),service:f.get("service"),status:"Recibido",due:f.get("due"),alert:"Pendiente",phone:f.get("phone"),email:f.get("email"),channel:f.get("channel"),pending:f.get("pending"),notes:f.get("notes"),observations:f.get("notes")?[{by:state.user.name,at:new Date().toLocaleString("es-CO"),text:f.get("notes")}]:[]};state.cases.unshift(item);try{await save()}catch(error){state.cases=state.cases.filter(c=>c.id!==item.id);alert(error.message);return}caseForm.reset();caseModal.classList.remove("visible");state.view="cases";render()};
observationForm.onsubmit=async e=>{e.preventDefault();const c=state.cases.find(x=>x.id===selectedCaseId);if(!c)return;const previous=JSON.parse(JSON.stringify(c));const next=detailStatus.value;c.status=next;c.delivery=detailDelivery.value;c.invoice=detailInvoice.value.trim();c.paymentDate=detailPayment.value;c.value=detailValue.value;c.paymentStatus=detailPaymentStatus.value;c.qualityStatus=detailQualityStatus.value;c.pending=detailPending.value.trim();if(next==="Terminado")c.alert="Pendiente de facturación";if(next==="Facturado")c.alert=c.paymentDate?"":"Pendiente de pago";const text=observationText.value.trim();if(text){c.observations=c.observations||[];c.observations.push({by:state.user.name,at:new Date().toLocaleString("es-CO"),text});}try{await save()}catch(error){Object.assign(c,previous);alert(error.message);return}detailModal.classList.remove("visible");render()};
detailPdfFiles.onchange=async e=>{const files=[...e.target.files].filter(file=>file.type==="application/pdf"||file.name.toLowerCase().endsWith(".pdf"));if(!selectedCaseId||!files.length)return;for(const file of files)await saveCaseDocument(selectedCaseId,file);e.target.value="";renderCaseDocuments(selectedCaseId)};
recoveryForm.onsubmit=async e=>{e.preventDefault();const username=recoveryUser.value.trim();let message="Solicitud registrada. Dirección General validará tu identidad y entregará un enlace o clave temporal por el canal corporativo.";try{const r=await fetch("/api/recovery-request",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({username})});if(r.ok){const data=await r.json();message=data.message||message;}}catch{}recoveryMessage.textContent=message;};
async function loadRecoveryRequests(){const target=$("#recoveryRequests");if(!target)return;try{const r=await fetch("/api/recovery-requests");const data=await r.json();if(!r.ok)throw new Error();target.className=data.length?"requestList":"empty";target.innerHTML=data.length?data.slice().reverse().map(x=>`<div class="requestRow"><strong>${esc(x.username)}</strong><span>${esc(x.status)}</span><small>${esc(x.requestedAt)}</small></div>`).join(""):"No hay solicitudes pendientes."}catch{target.textContent="No fue posible cargar las solicitudes."}}
async function loadActivity(){const target=$("#activityLog");if(!target)return;try{const r=await fetch("/api/activity");const data=await r.json();if(!r.ok)throw new Error();target.className=data.length?"activityList":"empty";target.innerHTML=data.length?data.map(x=>`<div class="activityRow"><strong>${esc(x.type)}</strong><span>${esc(x.username||x.by||"")}</span><small>${esc(x.at)}</small></div>`).join(""):"No hay actividad registrada."}catch{target.textContent="No fue posible cargar la actividad."}}
document.addEventListener("submit",async e=>{if(e.target.id!=="adminResetForm")return;e.preventDefault();const target=adminTarget.value,next=adminNewPassword.value;if(next.length<10){alert("La contraseña debe tener al menos 10 caracteres.");return}try{const r=await fetch("/api/admin/reset-password",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({username:target,newPassword:next})});const data=await r.json();if(!r.ok){alert(data.error||"No fue posible restablecer la contraseña.");return}alert("Contraseña temporal asignada.");adminResetForm.reset()}catch{alert("No fue posible conectar con el servidor.")}});
passwordForm.onsubmit=async e=>{e.preventDefault();const current=currentPassword.value,next=newPassword.value;if(next.length<10){passwordMessage.textContent="La nueva contraseña debe tener al menos 10 caracteres.";return}if(apiMode){try{const r=await fetch("/api/change-password",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({currentPassword:current,newPassword:next})});const data=await r.json();if(!r.ok){passwordMessage.textContent=data.error||"No fue posible cambiar la contraseña.";return}}catch{passwordMessage.textContent="No fue posible conectar con el servidor.";return}}else{if(current!==state.user.password){passwordMessage.textContent="La contraseña actual no coincide.";return}state.user.password=next;localStorage.setItem(`bcPassword:${state.user.username}`,next)}passwordMessage.textContent="Contraseña actualizada.";passwordForm.reset();};
let crmFolderPoller=null;let crmFolderSignature="";
async function connectFolderFromServer(){try{const response=await fetch("/api/local-folder/data",{cache:"no-store"});if(!response.ok)throw new Error();const payload=await response.json();crmFolderSignature=payload.files.map(file=>`${file.name}:${file.lastModified}:${file.size}`).join("|");const status=$("#syncStatus");if(status){status.className="syncBadge online";status.textContent="● Carpeta del CRM vinculada"}if(crmFolderPoller)clearInterval(crmFolderPoller);crmFolderPoller=setInterval(async()=>{try{const nextResponse=await fetch("/api/local-folder/data",{cache:"no-store"});if(!nextResponse.ok)throw new Error();const next=await nextResponse.json();const signature=next.files.map(file=>`${file.name}:${file.lastModified}:${file.size}`).join("|");if(signature!==crmFolderSignature){crmFolderSignature=signature;const nextStatus=$("#syncStatus");if(nextStatus){nextStatus.className="syncBadge syncing";nextStatus.textContent="● Sincronizando..."}window.dispatchEvent(new CustomEvent("crm:data-updated",{detail:{serverMode:true,root:next.root}}));setTimeout(()=>{if(nextStatus){nextStatus.className="syncBadge online";nextStatus.textContent="● Carpeta del CRM vinculada"}},600) }}catch{const nextStatus=$("#syncStatus");if(nextStatus){nextStatus.className="syncBadge offline";nextStatus.textContent="● Error de lectura"}}},2000);return true}catch{const status=$("#syncStatus");if(status){status.className="syncBadge offline";status.textContent="● Error de conexión"}return false}}
document.getElementById("btnConnectFolder")?.addEventListener("click",async()=>{if(window.folderWatcher?.connectFolder){const connected=await window.folderWatcher.connectFolder();if(connected)return}await connectFolderFromServer()});
window.addEventListener("crm:data-updated",()=>{cases=mergeCases();state.cases=cases;setup();if(state.user)render();});
function pensionSave(item){pensionDiagnostics.unshift(item);pensionDiagnostics=pensionDiagnostics.slice(0,100);localStorage.setItem("bcPensionDiagnostics",JSON.stringify(pensionDiagnostics));if(apiMode)fetch("/api/pension-diagnostics",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(item)}).catch(()=>{});}
function pensionReport(item,format){const r=item.result||{},html=`<html><head><meta charset="utf-8"><title>Diagnóstico pensional ${esc(item.name)}</title><style>body{font-family:Arial;color:#24313d;padding:36px}h1{color:#17324d}h2{color:#2f78c4}table{border-collapse:collapse;width:100%}td{border:1px solid #dbe3ea;padding:8px}.warn{background:#fff3d1;padding:12px}</style></head><body><h1>Diagnóstico Pensional BC Soluciones</h1><p><strong>Afiliado:</strong> ${esc(item.name)}<br><strong>Régimen:</strong> ${esc(item.regime)}<br><strong>Trámite:</strong> ${esc(item.procedure)}<br><strong>Fecha:</strong> ${esc(r.createdAt||"")}</p><h2>Resultado preliminar</h2><table><tr><td>Liquidación estimada</td><td>$${Number(r.estimated||0).toLocaleString("es-CO")}</td></tr><tr><td>Valor informado</td><td>$${Number(item.paid||0).toLocaleString("es-CO")}</td></tr><tr><td>Diferencia</td><td>$${Number(r.difference||0).toLocaleString("es-CO")}</td></tr><tr><td>Fórmula</td><td>${esc(r.formula||"")}</td></tr></table><h2>Observaciones</h2><ul>${(r.flags||[]).map(x=>`<li>${esc(x)}</li>`).join("")||"<li>No se identificaron alertas automáticas con los datos ingresados.</li>"}</ul><div class="warn"><strong>Revisión obligatoria:</strong> ${esc(r.review||"Pendiente de revisión profesional")}. Este documento es un apoyo preliminar y no constituye concepto jurídico.</div></body></html>`;if(format==="doc"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([html],{type:"application/msword"}));a.download=`diagnostico-pensional-${String(item.name).replace(/[^a-z0-9]+/gi,"-")}.doc`;a.click();return}const w=window.open();if(w){w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),300)}}
function renderPensionStandalone(){if(!pensionAccess()){content.innerHTML=pensionView();return}viewTitle.textContent="Diagnóstico pensional";document.querySelectorAll(".navItem").forEach(b=>b.classList.toggle("active",b.dataset.view==="pension"));content.innerHTML=pensionView();}
document.addEventListener("click",e=>{const btn=e.target.closest('[data-view="pension"]');if(!btn)return;e.preventDefault();e.stopImmediatePropagation();state.view="pension";renderPensionStandalone()},true);
document.addEventListener("submit",e=>{if(e.target.id==="pensionForm"){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const files=[...($("#pensionFiles")?.files||[])].map(f=>({name:f.name,size:f.size,type:f.type}));const result=pensionCalculate(data);const item={...data,documents:files,result,createdBy:state.user?.name||""};pensionSave(item);const target=$("#pensionResult");target.innerHTML=`<div class="pensionResult"><h3>Resultado preliminar</h3><div class="resultCards"><div><small>Liquidación estimada</small><strong>$${result.estimated.toLocaleString("es-CO")}</strong></div><div><small>Diferencia informada</small><strong>$${result.difference.toLocaleString("es-CO")}</strong></div></div><p><strong>Fórmula aplicada:</strong> ${esc(result.formula)}</p><ul>${result.flags.map(x=>`<li>${esc(x)}</li>`).join("")||"<li>Sin alertas automáticas con los datos ingresados.</li>"}</ul><div class="formActions"><button class="secondary" type="button" data-pension-report="doc">Descargar Word</button><button class="primary" type="button" data-pension-report="pdf">Generar PDF</button></div></div>`;target.dataset.item=JSON.stringify(item);return}if(e.target.id==="pensionAssistantForm"){e.preventDefault();const q=$("#pensionAssistantPrompt").value.toLowerCase();const answer=q.includes("indemn")?"Revisa edad, semanas, imposibilidad de continuar cotizando, base salarial promedio y porcentaje promedio de cotización. En RPM debe verificarse la fórmula del artículo 37 de la Ley 100 y el Decreto 1730 de 2001.":q.includes("trans")?"Solicita fecha de nacimiento, sexo, semanas acreditadas a la fecha de corte, régimen y administradora. La transición debe comprobarse con la regla vigente y documentos oficiales.":"Revisa historia laboral, resolución, factores salariales, IBL, semanas, régimen y soportes. El resultado requiere validación profesional.";$("#pensionAssistantResponse").innerHTML=`<p>${esc(answer)}</p>`}},false);
document.addEventListener("click",e=>{const b=e.target.closest("[data-pension-report]");if(!b)return;const item=JSON.parse($("#pensionResult").dataset.item||"null");if(item)pensionReport(item,b.dataset.pensionReport==="doc"?"doc":"pdf")});
document.addEventListener("click",async e=>{if(e.target.closest("#newMessage")){if(!apiMode){alert("Los mensajes internos están disponibles cuando el CRM está conectado al servidor.");return}$("#messageForm")?.reset();$("#messageFormStatus").textContent="";populateMessageDepartments();$("#messageModal").classList.add("visible");return}if(e.target.closest("#refreshMessages")){await loadMessages();render();return}const row=e.target.closest("[data-message-open]");if(!row)return;const message=state.messages.find(item=>item.id===row.dataset.messageOpen);if(!message)return;renderMessageDetail(message);if(apiMode&&message.fromUsername!==state.user.username&&!(message.readBy||[]).includes(state.user.username)){await fetch(`/api/messages/${encodeURIComponent(message.id)}/read`,{method:"PUT"});message.readBy.push(state.user.username);updateMessageBadge();row.classList.remove("unread")}});
document.addEventListener("submit",async e=>{if(e.target.id!=="messageForm")return;e.preventDefault();const form=e.target,status=$("#messageFormStatus"),submit=form.querySelector("button.primary");if(!apiMode){status.textContent="Conecta el CRM al servidor para enviar mensajes.";return}const files=[...($("#messageFiles")?.files||[])];if(files.length>5||files.some(file=>file.size>10*1024*1024)){status.textContent="Revisa el límite de 5 archivos y 10 MB por archivo.";return}submit.disabled=true;status.textContent="Enviando…";try{const response=await fetch("/api/messages",{method:"POST",body:new FormData(form)});const data=await response.json();if(!response.ok)throw new Error(data.error||"No fue posible enviar el mensaje");state.messages.unshift(data);form.reset();$("#messageModal").classList.remove("visible");state.view="messages";render();alert("Mensaje enviado al departamento destinatario.")}catch(error){status.textContent=error.message}finally{submit.disabled=false}});
async function restoreSession(){try{const response=await fetch("/api/session",{cache:"no-store"});if(!response.ok)return false;const remoteUser=await response.json();const casesResponse=await fetch("/api/cases",{cache:"no-store"});if(!casesResponse.ok)return false;state.cases=await casesResponse.json();const localUser=users.find(user=>user.username===remoteUser.username)||{};state.user={...localUser,...remoteUser};apiMode=true;apiAvailable=true;state.scope=state.user.all?"all":state.user.department;await Promise.all([loadTasks(),loadMessages(),loadCalendar(),loadCompanyProfile(),loadProspects()]);loginModal.classList.remove("visible");render();return true}catch(error){console.warn("No fue posible restaurar la sesión",error);return false}}
async function bootstrap(){try{const health=await fetch("/api/health",{cache:"no-store"});apiMode=health.ok;apiAvailable=health.ok;}catch{}setup();if(apiAvailable){const restored=await restoreSession();if(!restored){state.user=null;apiMode=false;loginModal.classList.add("visible");currentUserLabel.textContent="";}}else{loginModal.classList.add("visible");}}
bootstrap();
